    {isPPT : Adv → Prop} {isPPT' : Adv' → Prop}
    {reduce : Adv → Adv'}
    {ε : ℕ → ℝ≥0∞} (hε : negligible ε)
    (hreduce : ∀ A, isPPT A → isPPT' (reduce A))
    (hclose : ∀ A, isPPT A → ∀ n,
      g₁.advantage A n ≤ g₂.advantage (reduce A) n + ε n)
