private theorem sum_map_ite (l : List S) (p : S → Bool) (a b : ℝ≥0∞) :
    (l.map fun x => if p x then a else b).sum
      = (l.countP p : ℝ≥0∞) * a + (l.countP (fun x => !p x) : ℝ≥0∞) * b

private theorem sum_fin_ite (l : List S) (p : S → Bool) (a b : ℝ≥0∞) :
    ∑ i : Fin l.length, (if p l[(i : ℕ)] then a else b)
      = (l.countP p : ℝ≥0∞) * a + (l.countP (fun x => !p x) : ℝ≥0∞) * b

private lemma inv_natCast_pow_mul_inv_list_prod (qc : ι → ℕ) (j : ι) (js : List ι) (f : ι → ℕ) :
    ((↑(f j ^ qc j) : ENNReal))⁻¹ * (↑(js.map (fun j => f j ^ qc j)).prod)⁻¹ =
      (↑((j :: js).map (fun j => f j ^ qc j)).prod)⁻¹

