    {post : α → β → l}
    (h_none : oa = none → Triple pre x y post)
    (h_some : ∀ a, oa = some a → Triple pre (x' a) (y' a) post) :
    Triple pre (oa.elim x x') (oa.elim y y') post

theorem triple_sum_elim {α' β' : Type u} (s : α' ⊕ β') {pre : l}
